contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Make a deposit so the caller has a balance to collect.
        c.Deposit{value: depositAmount}();

        uint beforeBalance = c.balances(address(this));
        uint beforeContractEther = address(c).balance;
        uint beforeTestEther = address(this).balance;

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint afterBalance = c.balances(address(this));
            assert(afterBalance + collectAmount == beforeBalance &&
                   address(c).balance + collectAmount == beforeContractEther &&
                   address(this).balance == beforeTestEther + collectAmount);
        } else {
            // A revert must leave all observable values unchanged.
            assert(c.balances(address(this)) == beforeBalance &&
                   address(c).balance == beforeContractEther &&
                   address(this).balance == beforeTestEther);
        }
    }

    receive() external payable {}
}

