contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount, "not enough balance");

        c.Deposit{value: depositAmount}();

        c.SetMinSum(0);
        c.Initialized();

        uint beforeUserBalance = c.balances(address(this));
        uint beforeContractBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterUserBalance = c.balances(address(this));
        uint afterContractBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;

        if (!reverted) {
            assert(
                afterUserBalance == beforeUserBalance - collectAmount &&
                afterContractBalance == beforeContractBalance - collectAmount &&
                afterThisBalance == beforeThisBalance + collectAmount &&
                afterContractBalance == c.balances(address(this))
            );
        } else {
            assert(
                afterUserBalance == beforeUserBalance &&
                afterContractBalance == beforeContractBalance &&
                afterThisBalance == beforeThisBalance
            );
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount > 0, "amount must be positive");

        uint256 balBefore = c.balances(address(this));
        uint256 cEtherBefore = address(c).balance;

        try c.Collect(amount) {
            uint256 balAfter = c.balances(address(this));
            uint256 cEtherAfter = address(c).balance;
            assert(balAfter <= balBefore && cEtherAfter <= cEtherBefore);
        } catch {
            uint256 balAfter = c.balances(address(this));
            uint256 cEtherAfter = address(c).balance;
            assert(balAfter == balBefore && cEtherAfter == cEtherBefore);
        }
    }

    receive() external payable {}
}

